const { pulse, history } = $input.first().json.body ?? {};
const validPulse = value => Number.isInteger(value) && value >= 1 && value <= 350;
const items = json => [{ json }];
if (!validPulse(pulse) || !Array.isArray(history) || history.length > 30 || !history.every(validPulse)) {
  return items({ status: 'invalid_input' });
}

const sampleCount = history.length;
if (sampleCount < 4) return items({ status: 'insufficient_history', sampleCount });
return items({ pulse, history, sampleCount });

const input = $input.first().json;
if (input.status) return [{ json: input }];

const { pulse, history, sampleCount } = input;
function median(values) {
  const ordered = [...values].sort((a, b) => a - b);
  const upper = Math.floor(ordered.length / 2);
  return (ordered[Math.floor((ordered.length - 1) / 2)] + ordered[upper]) / 2;
}

const center = median(history);
const mad = median(history.map(value => Math.abs(value - center)));
const calibrationDistances = history.map((value, index) => {
  const reference = history.filter((_, candidate) => candidate !== index);
  const differences = reference.map(sample => Math.abs(value - sample)).sort((a, b) => a - b);
  return (differences[0] + differences[1]) / 2;
});

return [{ json: { pulse, history, sampleCount, center, mad, neighborThreshold: Math.max(12, 3 * median(calibrationDistances)) } }];

const input = $input.first().json;
if (input.status) return [{ json: input }];

const { pulse, history, sampleCount, center, mad, neighborThreshold } = input;
const differences = history.map(sample => Math.abs(pulse - sample)).sort((a, b) => a - b);
const neighborDistance = (differences[0] + differences[1]) / 2;
const centerDistance = Math.abs(pulse - center);
// MAD escalada para expresar la dispersión en las mismas unidades que el pulso.
const centerThreshold = Math.max(12, 3 * 1.4826 * mad);
const neighborSignal = neighborDistance > neighborThreshold;
const centerSignal = centerDistance > centerThreshold;

return [{ json: {
  status: neighborSignal && centerSignal ? 'atypical' : 'typical',
  sampleCount, direction: pulse > center ? 'above' : pulse < center ? 'below' : 'center',
  evidence: { center, mad, neighborDistance, neighborThreshold, centerDistance, centerThreshold, neighborSignal, centerSignal },
} }];

const { status, sampleCount, direction, evidence } = $input.first().json;
const explanations = {
  invalid_input: 'La medición o el historial tienen un formato inválido.',
  insufficient_history: 'Se necesitan al menos cuatro mediciones previas.',
  atypical: direction === 'above'
    ? 'La frecuencia está por encima del patrón habitual y lejos de sus lecturas más parecidas.'
    : 'La frecuencia está por debajo del patrón habitual y lejos de sus lecturas más parecidas.',
  typical: 'Los dos criterios del modelo no coincidieron en señalar una desviación.',
};

return [{ json: { status, explanation: explanations[status], sampleCount, direction, evidence } }];
